const e = $json.execution || {};
const msg = e.error?.message || '';
// "returned 0 homes": an empty result. "returned items Inky can't read": the site changed its format.
const m = msg.match(/Step (.+?) returned (?:0 homes|items Inky can't read)/);
const state = $getWorkflowStaticData('global');
state.fixes = (state.fixes || []).filter((t) => Date.now() - t < 3600e3);
if (state.fixes.length) return [];  // safety limit: one message and one fix per hour, then a human decides
state.fixes.push(Date.now());
return [{ json: { workflowId: $json.workflow.id, name: $json.workflow.name, step: m ? m[1] : e.lastNodeExecuted, error: msg } }];

const SCHEMAS = {"igolaizola~idealista-scraper": {"maxItems": {"type": "integer"}, "operation": {"type": "string", "enum": ["sale", "rent"]}, "propertyType": {"type": "string", "enum": ["newDevelopments", "homes", "bedrooms", "vacationRentals", "garages", "storageRooms", "offices", "premises", "transfers", "lands", "buildings"]}, "country": {"type": "string", "enum": ["es", "pt", "it", "fr"]}, "location": {"type": "string"}, "locations": {"type": "array"}, "postalCodes": {"type": "array"}, "latitude": {"type": "number"}, "longitude": {"type": "number"}, "distanceKm": {"type": "integer"}, "propertyCodes": {"type": "array"}, "sortBy": {"type": "string", "enum": ["relevance", "closest", "lowestPrice", "highestPrice", "mostRecent", "leastRecent", "highestPriceReduction", "lowestPriceM2", "highestPriceM2", "biggest", "smallest", "highestFloors"]}, "fetchDetails": {"type": "boolean"}, "fetchStats": {"type": "boolean"}, "minPrice": {"type": "string", "enum": ["0", "500", "550", "600", "650", "700", "750", "800", "850", "900", "950", "1000"]}, "maxPrice": {"type": "string", "enum": ["0", "500", "550", "600", "650", "700", "750", "800", "850", "900", "950", "1000"]}, "minSize": {"type": "string", "enum": ["0", "60", "80", "100", "120", "140", "160", "180", "200", "220", "240", "260"]}, "maxSize": {"type": "string", "enum": ["0", "60", "80", "100", "120", "140", "160", "180", "200", "220", "240", "260"]}, "publicationDate": {"type": "string", "enum": ["", "Y", "T", "W", "M"]}, "rentalTypes": {"type": "array"}, "bedrooms": {"type": "array"}, "bathrooms": {"type": "array"}, "homeType": {"type": "array"}, "condition": {"type": "array"}, "propertyStatus": {"type": "array"}, "floor": {"type": "array"}, "bankOffer": {"type": "boolean"}, "airConditioning": {"type": "boolean"}, "fittedWardrobes": {"type": "boolean"}, "lift": {"type": "boolean"}, "balcony": {"type": "boolean"}, "terrace": {"type": "boolean"}, "exterior": {"type": "boolean"}, "garage": {"type": "boolean"}, "garden": {"